#!/usr/bin/env python3

import math

# automatically trigger ANTLR4 Java tool, if we fail to import the files
# generated by it

try:
    from gelb.antlr_part.generated_code.GeLBParser import GeLBParser
    from gelb.antlr_part.generated_code.GeLBVisitor import GeLBVisitor
except ModuleNotFoundError:
    from gelb.utils.misc import invoke_antlr4_tool
    invoke_antlr4_tool()
    from gelb.antlr_part.generated_code.GeLBParser import GeLBParser
    from gelb.antlr_part.generated_code.GeLBVisitor import GeLBVisitor

from gelb.gelb_ast.ASTNodes import *
from gelb.utils.CodeRange import code_range_from_ctx
from gelb.utils.exceptions import *
from gelb.frontend.type_rules import reject_if_not_in_this_version


# INPUT: ANTLR4-generated ParseTree
# OUTPUT: GeLB AST (*root* node)
class ASTBuilderVisitor(GeLBVisitor):
    """
    Visitor for the ANTLR4-generated concrete syntax tree (CST), also known
    sometimes as "syntax trees".

    When we invoke the ``visitGelb_program`` method, we get a complete initial
    abstract syntax tree (AST) for a GeLB program. When we invoke one of the
    other ``visitX`` methods, we get GeLB AST sub-trees.

    NOTE: Unfortunately, there is a lot of confusion related to CSTs and ASTs,
    with people confusing these two (related) concepts. In GeLB, we denote the
    result produced by the ANTLR4-generated parser the CST. This
    ``ASTBuilderVisitor`` class takes that CST and builds the AST, which is a
    customized (manually-designed) tree of nodes, which serves as the
    intermediate representation (IR) for the whole ``gelbc`` compiler. The other
    visitors (derived from ``ASTBaseVisitor``) implement operations on the AST
    (and have no knowledge of the CST).
    """

    def __init__(self):
        self.instances_set_simulation_description_stmt = 0
        self.instances_global_constants_block = 0
        self.instances_lattices_block = 0
        self.instances_initializer_block = 0
        self.instances_dynamic_block = 0
        self.instances_gauge_block = 0
        self.instances_function_block = 0
        self.instances_node_classes_block = 0
        self.instances_geometry_block = 0

    # Visit a parse tree produced by GeLBParser#gelb_program.
    def visitGelb_program(
            self,
            ctx: GeLBParser.Gelb_programContext
    ):
        """
        During this stage, we are accepting all possible high-level blocks,
        and constructing the whole-program AST.
        """
        result = Program_N(  # creates empty =Program_N=
            code_range_from_ctx(ctx)
        )
        list_of_children_sub_asts = self.get_list_of_children_sub_asts(ctx)
        
        for child in list_of_children_sub_asts:
            if isinstance(child, SetSimulationDescriptionStmt_N):
                result.simulation_description = child.description
            elif isinstance(child, GlobalConstantsBlock_N):
                result.global_constants = child
            elif isinstance(child, LatticesBlock_N):
                result.lattices = child
            elif isinstance(child, InitializerBlock_N):
                if result.initializers is None:
                    result.initializers = List_N(
                        # In the case of blocks which may have several
                        # instances (such as =InitializerBlock_N=,
                        # =DynamicBlock_N=, =GaugeBlock_N=,
                        # =FunctionBlock_N=), we have no guarantee that all
                        # blocks of the same type are provided in the program
                        # one after the other, so it makes no sense to define
                        # a =code_range= for the list of blocks of these
                        # types -> we simply pass =None=.
                        code_range=None
                    )
                result.initializers.append(child)
            elif isinstance(child, DynamicBlock_N):
                if result.dynamics is None:
                    result.dynamics = List_N(
                        # see comment for =result.initializers=
                        code_range=None
                    )
                result.dynamics.append(child)
            elif isinstance(child, GaugeBlock_N):
                if result.gauges is None:
                    result.gauges = List_N(
                        # see comment for =result.initializers=
                        code_range=None
                    )
                result.gauges.append(child)
            elif isinstance(child, FunctionBlock_N):
                if result.functions is None:
                    result.functions = List_N(
                        # see comment for =result.initializers=
                        code_range=None
                    )
                result.functions.append(child)
            elif isinstance(child, NodeClassesBlock_N):
                result.node_classes = child
            elif isinstance(child, GeometryBlock_N):
                result.geometry = child

        # ensure that no mandatory block is missing
        if self.instances_set_simulation_description_stmt == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "set_simulation_description_stmt",
                self.instances_set_simulation_description_stmt,
                None, None
            )
        if self.instances_lattices_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "lattices_block",
                self.instances_lattices_block,
                None, None
            )
        if self.instances_initializer_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "initializer_block",
                self.instances_initializer_block,
                None, None
            )
        if self.instances_dynamic_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "dynamic_block",
                self.instances_dynamic_block,
                None, None
            )
        if self.instances_gauge_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "gauge_block",
                self.instances_gauge_block,
                None, None
            )
        if self.instances_node_classes_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "node_classes_block",
                self.instances_node_classes_block,
                None, None
            )
        if self.instances_geometry_block == 0:
            raise GeLBExInvalidNoOfOccurrences(
                "geometry_block",
                self.instances_geometry_block,
                None, None
            )

        return result

    # Visit a parse tree produced by GeLBParser#set_simulation_description_stmt.
    def visitSet_simulation_description_stmt(
            self,
            ctx: GeLBParser.Set_simulation_description_stmtContext
    ):
        self.instances_set_simulation_description_stmt += 1
        # prevent more than one instance
        if self.instances_set_simulation_description_stmt > 1:
            raise GeLBExInvalidNoOfOccurrences(
                "set_simulation_description_stmt",
                self.instances_set_simulation_description_stmt,
                ctx.start.line,
                ctx.start.column
            )
        string_text = ctx.STRING_LITERAL().getText()  # Keep quotes for now
        return SetSimulationDescriptionStmt_N(
            code_range_from_ctx(ctx),
            StringLiteral_N(code_range_from_ctx(ctx), string_text)
        )

    # Visit a parse tree produced by GeLBParser#global_constants_block.
    def visitGlobal_constants_block(
            self,
            ctx: GeLBParser.Global_constants_blockContext
    ):
        self.instances_global_constants_block += 1
        # prevent more than one instance
        if self.instances_global_constants_block > 1:
            raise GeLBExInvalidNoOfOccurrences(
                "global_constants_block",
                self.instances_global_constants_block,
                ctx.start.line,
                ctx.start.column
            )
        return GlobalConstantsBlock_N(
            code_range_from_ctx(ctx),
            self.get_list_of_children_sub_asts(ctx)
        )

    # Visit a parse tree produced by GeLBParser#lattices_block.
    def visitLattices_block(
            self,
            ctx: GeLBParser.Lattices_blockContext
    ):
        self.instances_lattices_block += 1
        # prevent more than one instance
        if self.instances_lattices_block > 1:
            raise GeLBExInvalidNoOfOccurrences(
                "lattices_block",
                self.instances_lattices_block,
                ctx.start.line,
                ctx.start.column
            )
        return LatticesBlock_N(
            code_range_from_ctx(ctx),
            self.get_list_of_children_sub_asts(ctx)
        )

    # Visit a parse tree produced by GeLBParser#lattice_insta_stmt.
    def visitLattice_insta_stmt(
            self,
            ctx: GeLBParser.Lattice_insta_stmtContext
    ):
        return LatticeInstaStmt_N(
            code_range_from_ctx(ctx),
            self.visit(ctx.name),
            self.visit(ctx.d),
            self.visit(ctx.q),
            self.visit(ctx.df_type),
            self.visit(ctx.grid_size),     # NEW: grid size parameter
            self.visit(ctx.periodicity)    # NEW: periodicity parameter
        )

    # Visit a parse tree produced by GeLBParser#singleElementRange.
    def visitSingleElementRange(
            self,
            ctx: GeLBParser.SingleElementRangeContext
    ):
        low_and_high = self.visit(ctx.low)
        return Range_N(
            code_range_from_ctx(ctx),
            low_and_high,
            low_and_high
        )

    # Visit a parse tree produced by GeLBParser#lowhighBoundRange.
    def visitLowhighBoundRange(
            self,
            ctx: GeLBParser.LowhighBoundRangeContext
    ):
        low = self.visit(ctx.low)
        high = self.visit(ctx.high)
        return Range_N(
            code_range_from_ctx(ctx),
            low,
            high
        )

    # Visit a parse tree produced by GeLBParser#lowBoundRange.
    def visitLowBoundRange(
            self,
            ctx: GeLBParser.LowBoundRangeContext
    ):
        low = self.visit(ctx.low)
        return Range_N(
            code_range_from_ctx(ctx),
            low,
            None
        )

    # Visit a parse tree produced by GeLBParser#highBoundRange.
    def visitHighBoundRange(
            self,
            ctx: GeLBParser.HighBoundRangeContext
    ):
        high = self.visit(ctx.high)
        return Range_N(
            code_range_from_ctx(ctx),
            None,
            high
        )

    # Visit a parse tree produced by GeLBParser#allElementsRange.
    def visitAllElementsRange(
            self,
            ctx: GeLBParser.AllElementsRangeContext
    ):
        return Range_N(
            code_range_from_ctx(ctx),
            None,
            None
        )

    # Visit a parse tree produced by GeLBParser#coordinates_range
    def visitCoords_range(
            self,
            ctx: GeLBParser.Coords_rangeContext
    ):
        if isinstance(ctx, GeLBParser.SingleElementRangeContext):
            return self.visitSingleElementRange(ctx)
        elif isinstance(ctx, GeLBParser.LowhighBoundRangeContext):
            return self.visitLowhighBoundRange(ctx)
        elif isinstance(ctx, GeLBParser.LowBoundRangeContext):
            return self.visitLowBoundRange(ctx)
        elif isinstance(ctx, GeLBParser.HighBoundRangeContext):
            return self.visitHighBoundRange(ctx)
        elif isinstance(ctx, GeLBParser.AllElementsRangeContext):
            return Range_N(
                code_range_from_ctx(ctx),
                None,
                None
            )

    # Visit a parse tree produced by GeLBParser#initializer_block.
    def visitInitializer_block(
            self,
            ctx: GeLBParser.Initializer_blockContext
    ):
        name = self.visit(ctx.identifier())
        stmts = List_N(code_range_from_ctx(ctx))
        for stmt in ctx.block_stmt():
            stmts.append(self.visit(stmt))
        self.instances_initializer_block += 1
        return InitializerBlock_N(code_range_from_ctx(ctx), name, stmts)

    # Visit a parse tree produced by GeLBParser#dynamic_block.
    def visitDynamic_block(
            self,
            ctx: GeLBParser.Dynamic_blockContext
    ):
        name = self.visit(ctx.identifier())
        stmts = List_N(code_range_from_ctx(ctx))
        for stmt in ctx.block_stmt():
            stmts.append(self.visit(stmt))
        self.instances_dynamic_block += 1
        return DynamicBlock_N(code_range_from_ctx(ctx), name, stmts)

    # Visit a parse tree produced by GeLBParser#gauge_block.
    def visitGauge_block(
            self,
            ctx: GeLBParser.Gauge_blockContext
    ):
        name = self.visit(ctx.name)

        outputs = List_N(code_range_from_ctx(ctx))
        for output in ctx.results:
            outputs.append(self.visit(output))
        
        stmts = List_N(code_range_from_ctx(ctx.block_stmt()))
        for stmt in ctx.block_stmt():
            stmts.append(self.visit(stmt))
        self.instances_gauge_block += 1
        return GaugeBlock_N(
            code_range_from_ctx(ctx),
            name,
            outputs,
            stmts
        )

    # Visit a parse tree produced by GeLBParser#function_block.
    def visitFunction_block(
            self,
            ctx: GeLBParser.Function_blockContext
    ):
        name = self.visit(ctx.name)

        inputs = List_N(code_range_from_ctx(ctx))
        for inp in ctx.params:
            inputs.append(self.visit(inp))

        outputs = List_N(code_range_from_ctx(ctx))
        for out in ctx.results:
            outputs.append(self.visit(out))

        stmts = List_N(code_range_from_ctx(ctx))
        for stmt in ctx.block_stmt():
            stmts.append(self.visit(stmt))

        self.instances_function_block += 1
        return FunctionBlock_N(code_range_from_ctx(ctx), name, inputs, outputs, stmts)

    # Visit a parse tree produced by GeLBParser#destructuring_assignment_stmt.
    def visitDestructuring_assignment_stmt(
            self,
            ctx: GeLBParser.Destructuring_assignment_stmtContext
    ):
        targets = List_N(code_range_from_ctx(ctx))
        for target_ctx in ctx.targets:
            targets.append(self.visit(target_ctx))

        rhs = self.visit(ctx.rhs)
        return DestructuringAssignmentStmt_N(code_range_from_ctx(ctx), targets, rhs)

    # Visit a parse tree produced by GeLBParser#node_classes_block.
    def visitNode_classes_block(
            self,
            ctx: GeLBParser.Node_classes_blockContext
    ):
        self.instances_node_classes_block += 1
        # prevent more than one instance
        if self.instances_node_classes_block > 1:
            raise GeLBExInvalidNoOfOccurrences(
                "node_classes_block",
                self.instances_node_classes_block,
                ctx.start.line,
                ctx.start.column
            )
        node_classes = List_N(code_range_from_ctx(ctx))
        for node_class in ctx.node_class_insta_stmt():
            node_classes.append(self.visit(node_class))
        self.instances_node_classes_block += 1
        return NodeClassesBlock_N(code_range_from_ctx(ctx), node_classes)

    # Visit a parse tree produced by GeLBParser#node_class_insta_stmt.
    def visitNode_class_insta_stmt(
            self,
            ctx: GeLBParser.Node_class_insta_stmtContext
    ):
        ids = ctx.identifier()
        name = self.visit(ids[0])
        masked = ctx.MASKED() is not None

        if masked:
            if len(ids) == 1:
                # node_class SOLID() masked;
                initializer = None
                dynamic = None
            elif len(ids) == 2:
                # node_class SW(Init) masked;
                initializer = self.visit(ids[1])
                dynamic = None
            else:
                # node_class WALL(Init, BB) masked;
                initializer = self.visit(ids[1])
                dynamic = self.visit(ids[2])
            gauge = None
        else:
            initializer = self.visit(ids[1])
            if len(ids) == 4:
                # node_class NAME(init, dynamic, gauge);
                dynamic = self.visit(ids[2])
                gauge = self.visit(ids[3])
            else:
                # node_class NAME(init, gauge);  -- no dynamic (static node)
                dynamic = None
                gauge = self.visit(ids[2])

        return NodeClassInstaStmt_N(code_range_from_ctx(ctx),
                                    name, initializer, dynamic, gauge,
                                    masked=masked)

    # Visit a parse tree produced by GeLBParser#geometry_block.
    def visitGeometry_block(
            self,
            ctx: GeLBParser.Geometry_blockContext
    ):
        self.instances_geometry_block += 1
        # prevent more than one instance
        if self.instances_geometry_block > 1:
            raise GeLBExInvalidNoOfOccurrences(
                "geometry_block",
                self.instances_geometry_block,
                ctx.start.line,
                ctx.start.column
            )
        stmts = List_N(code_range_from_ctx(ctx))
        for stmt in ctx.geometry_stmt():
            stmts.append(self.visit(stmt))
        return GeometryBlock_N(
            code_range_from_ctx(ctx),
            stmts
        )

    # Visit a parse tree produced by GeLBParser#geometry_stmt.
    def visitGeometry_stmt(
            self,
            ctx: GeLBParser.Geometry_stmtContext
    ):
        # Transparent pass-through to the actual statement type
        return self.visit(ctx.getChild(0))

    # Visit a parse tree produced by GeLBParser#paint_nodes_stmt.
    def visitPaint_nodes_stmt(
            self,
            ctx: GeLBParser.Paint_nodes_stmtContext
    ):
        node_class = self.visit(ctx.identifier())
        spatial_ranges = List_N(code_range_from_ctx(ctx))
        for r in ctx.coords_range():
            spatial_ranges.append(self.visit(r))
        return PaintNodesStmt_N(code_range_from_ctx(ctx),
                                spatial_ranges, node_class)

    # Visit a parse tree produced by GeLBParser#conditional_paint_stmt.
    def visitConditional_paint_stmt(
            self,
            ctx: GeLBParser.Conditional_paint_stmtContext
    ):
        node_class = self.visit(ctx.node_class)
        predicate = self.visit(ctx.predicate)
        return ConditionalPaintStmt_N(
            code_range_from_ctx(ctx), predicate, node_class)

    # Visit a parse tree produced by GeLBParser#border_stmt.
    def visitBorder_stmt(
            self,
            ctx: GeLBParser.Border_stmtContext
    ):
        source = self.visit(ctx.source)
        target = self.visit(ctx.target)
        return BorderStmt_N(code_range_from_ctx(ctx), source, target)

    # Visit a parse tree produced by
    # GeLBParser#lattice_out_selection_assignment_stmt.
    def visitLattice_out_selection_assignment_stmt(
            self,
            ctx: GeLBParser.Lattice_out_selection_assignment_stmtContext
    ):
        lhs = self.visit(ctx.lhs)
        rhs = self.visit(ctx.rhs)
        return LatticeOutSelectionAssignmentStmt_N(
            code_range_from_ctx(ctx),
            lhs, rhs
        )

    # Visit a parse tree produced by GeLBParser#array_selection_assignment_stmt.
    def visitArray_selection_assignment_stmt(
            self,
            ctx: GeLBParser.Array_selection_assignment_stmtContext
    ):
        lhs = self.visit(ctx.lhs)
        rhs = self.visit(ctx.rhs)
        return ArraySelectionAssignmentStmt_N(
            code_range_from_ctx(ctx),
            lhs, rhs
        )

    # Visit a parse tree produced by GeLBParser#rect_sel_of_lattice_in_dfs.
    def visitRect_sel_of_lattice_in_dfs(
            self,
            ctx: GeLBParser.Rect_sel_of_lattice_in_dfsContext
    ):
        name = self.visit(ctx.lattice_name)
        ranges = List_N(code_range_from_ctx(ctx))
        for r in ctx.spatial_ranges:
            ranges.append(self.visit(r))
        ranges.append(self.visit(ctx.dfs_range))

        return RectSelOfLatticeInDFs_N(
            code_range_from_ctx(ctx),
            name,
            ranges
        )

    # Visit a parse tree produced by GeLBParser#rect_sel_of_lattice_out_dfs.
    def visitRect_sel_of_lattice_out_dfs(
            self,
            ctx: GeLBParser.Rect_sel_of_lattice_out_dfsContext
    ):
        name = self.visit(ctx.lattice_name)
        ranges = List_N(code_range_from_ctx(ctx))
        for r in ctx.spatial_ranges:
            ranges.append(self.visit(r))
        ranges.append(self.visit(ctx.dfs_range))
        return RectSelOfLatticeOutDFs_N(
            code_range_from_ctx(ctx),
            name,
            ranges
        )

    # Visit a parse tree produced by GeLBParser#rect_sel_of_array_elems.
    def visitRect_sel_of_array_elems(
            self,
            ctx: GeLBParser.Rect_sel_of_array_elemsContext
    ):
        name = self.visit(ctx.array_name)
        ranges = List_N(code_range_from_ctx(ctx))
        for r in ctx.ranges:
            ranges.append(self.visit(r))
        return RectSelOfArrayElems_N(
            code_range_from_ctx(ctx),
            name,
            ranges
        )

    # Visit a parse tree produced by GeLBParser#rectSelOfArrayElemsExpr.
    # def visitRectSelOfArrayElemsExpr(
    #         self,
    #         ctx: GeLBParser.RectSelOfArrayElemsExprContext
    # ):
    #     name = self.visit(ctx.identifier())
    #     ranges = List_N(code_range_from_ctx(ctx.coords_range()))
